import os
import csv
import datetime

def excel_to_csv(excel_path, csv_path=None, sheet=0, delimiter=',', encoding='utf-8-sig'):
    """
    Convert an Excel file (.xls or .xlsx) to CSV.

    Parameters:
    - excel_path: path to the source Excel file (.xls or .xlsx).
    - csv_path: optional path to the destination CSV file. If None, same directory and base name used with .csv.
    - sheet: sheet index (int, zero-based) or sheet name (str) to convert. Default is 0 (first sheet).
    - delimiter: CSV delimiter (default ',').
    - encoding: file encoding for output CSV (default 'utf-8-sig' to help Excel detect UTF-8).

    Returns:
    - Path to the written CSV file.

    Notes:
    - Uses openpyxl for .xlsx and xlrd for .xls.
    - Dates/times are written using ISO format.
    """
    if not os.path.isfile(excel_path):
        raise FileNotFoundError(f"Excel file not found: {excel_path}")

    base, ext = os.path.splitext(excel_path)
    ext = ext.lower()
    if csv_path is None:
        csv_path = base + '.csv'

    def _format_value(v):
        if v is None:
            return ''
        if isinstance(v, (datetime.datetime, datetime.date, datetime.time)):
            # Use ISO format for dates/times
            return v.isoformat()
        if isinstance(v, bytes):
            try:
                return v.decode('utf-8')
            except Exception:
                return v.decode('latin-1', errors='replace')
        return str(v)

    # .xlsx handling with openpyxl
    if ext in ('.xlsx', '.xlsm', '.xltx', '.xltm'):
        try:
            from openpyxl import load_workbook
        except ImportError:
            raise ImportError("openpyxl is required for .xlsx files. Install with: pip install openpyxl")
        wb = load_workbook(excel_path, read_only=True, data_only=True)
        # select sheet
        if isinstance(sheet, int):
            try:
                ws = wb.worksheets[sheet]
            except IndexError:
                raise IndexError(f"Sheet index {sheet} out of range (0..{len(wb.worksheets)-1})")
        else:
            if sheet not in wb.sheetnames:
                raise KeyError(f"Sheet name '{sheet}' not found. Available: {wb.sheetnames}")
            ws = wb[sheet]

        with open(csv_path, 'w', newline='', encoding=encoding) as f:
            writer = csv.writer(f, delimiter=delimiter)
            for row in ws.iter_rows(values_only=True):
                writer.writerow([_format_value(cell) for cell in row])

    # .xls handling with xlrd
    elif ext == '.xls':
        try:
            import xlrd
        except ImportError:
            raise ImportError("xlrd is required for .xls files. Install with: pip install xlrd")
        wb = xlrd.open_workbook(excel_path, on_demand=True)
        if isinstance(sheet, int):
            try:
                sh = wb.sheet_by_index(sheet)
            except IndexError:
                raise IndexError(f"Sheet index {sheet} out of range (0..{wb.nsheets-1})")
        else:
            try:
                sh = wb.sheet_by_name(sheet)
            except xlrd.biffh.XLRDError:
                raise KeyError(f"Sheet name '{sheet}' not found. Available: {wb.sheet_names()}")
        with open(csv_path, 'w', newline='', encoding=encoding) as f:
            writer = csv.writer(f, delimiter=delimiter)
            for r in range(sh.nrows):
                row = sh.row_values(r)
                # xlrd may return floats for empty cells as 0.0 or '' depending; convert each:
                writer.writerow([_format_value(cell) for cell in row])
        wb.release_resources()

    else:
        raise ValueError(f"Unsupported Excel file extension: {ext}. Supported: .xls, .xlsx, .xlsm, .xltx, .xltm")

    return csv_path
```

Example usage:
- Convert first sheet from sample.xlsx into sample.csv:
  excel_to_csv("sample.xlsx")
- Convert a named sheet from an .xls file to a specific path:
  excel_to_csv("old.xls", "out.csv", sheet="Sheet1")

