Here's a self-contained Python function that uses the xmlmapper library to convert an XML string into a dictionary-like structure and saves it as a JSON file. The function tries a few common xmlmapper entry points, falls back to parsing with ElementTree if needed, and converts results into JSON-serializable built-in types.

Note: xmlmapper must be installed in your environment (pip install xmlmapper). The function will raise an ImportError with guidance if it's not installed.

```python
def xml_to_json_file(xml_string: str, json_path: str, *, encoding: str = "utf-8", indent: int = 2) -> None:
    """
    Convert an XML string to a dictionary representation using xmlmapper and save as a JSON file.

    Parameters:
    - xml_string (str): The XML content to convert.
    - json_path (str): Path to write the resulting JSON file.
    - encoding (str): File encoding for the output JSON (default "utf-8").
    - indent (int): Indentation level for pretty JSON (default 2).

    Raises:
    - ImportError: If xmlmapper is not installed.
    - ValueError: If parsing fails or the result cannot be converted.
    - OSError: If writing the JSON file fails.
    """
    import json
    try:
        import xmlmapper
    except ImportError as e:
        raise ImportError(
            "The xmlmapper library is required but not installed. Install it with: pip install xmlmapper"
        ) from e

    import xml.etree.ElementTree as ET

    # Try several common xmlmapper APIs to parse the string
    def parse_with_xmlmapper(s: str):
        attempts = []
        if hasattr(xmlmapper, "parse"):
            attempts.append(lambda x: xmlmapper.parse(x))
        if hasattr(xmlmapper, "from_string"):
            attempts.append(lambda x: xmlmapper.from_string(x))
        if hasattr(xmlmapper, "loads"):
            attempts.append(lambda x: xmlmapper.loads(x))
        if hasattr(xmlmapper, "XmlMapper"):
            Xm = getattr(xmlmapper, "XmlMapper")
            # try common instance methods
            attempts.append(lambda x: Xm().from_string(x) if hasattr(Xm(), "from_string") else Xm().map(x))
        # try attempts in order
        last_exc = None
        for fn in attempts:
            try:
                result = fn(s)
                # accept even falsy results (e.g., empty dict) but require no exception
                return result
            except Exception as ex:
                last_exc = ex
                continue
        # fallback: try ElementTree
        try:
            return ET.fromstring(s)
        except Exception as ex:
            raise ValueError("Failed to parse XML with xmlmapper and fallback ElementTree.") from (last_exc or ex)

    # Convert various object types into JSON-serializable builtins
    def to_builtin(obj):
        # simple types
        if obj is None or isinstance(obj, (str, int, float, bool)):
            return obj
        # dict-like
        if isinstance(obj, dict):
            return {str(k): to_builtin(v) for k, v in obj.items()}
        # iterable sequences
        if isinstance(obj, (list, tuple, set)):
            return [to_builtin(v) for v in obj]
        # ElementTree element
        if isinstance(obj, ET.Element):
            d = {}
            if obj.attrib:
                d["@attributes"] = dict(obj.attrib)
            text = (obj.text or "").strip()
            if text:
                d["#text"] = text
            for child in obj:
                child_key = child.tag
                child_val = to_builtin(child)
                # combine repeated tags into lists
                if child_key in d:
                    if not isinstance(d[child_key], list):
                        d[child_key] = [d[child_key]]
                    d[child_key].append(child_val)
                else:
                    d[child_key] = child_val
            return d
        # namedtuple-like
        if hasattr(obj, "_asdict"):
            try:
                return to_builtin(obj._asdict())
            except Exception:
                pass
        # mapping-like (items)
        if hasattr(obj, "items") and callable(getattr(obj, "items")):
            try:
                return {str(k): to_builtin(v) for k, v in obj.items()}
            except Exception:
                pass
        # object with __dict__
        if hasattr(obj, "__dict__"):
            try:
                return {str(k): to_builtin(v) for k, v in vars(obj).items() if not k.startswith("_")}
            except Exception:
                pass
        # final fallback: convert to string
        return str(obj)

    # Parse and convert
    parsed = parse_with_xmlmapper(xml_string)
    converted = to_builtin(parsed)

    # Ensure converted is JSON serializable by trying to dump to string first
    try:
        json_text = json.dumps(converted, ensure_ascii=False, indent=indent)
    except TypeError as ex:
        raise ValueError("Converted XML could not be serialized to JSON.") from ex

    # Write out the JSON file
    try:
        with open(json_path, "w", encoding=encoding) as f:
            f.write(json_text)
    except OSError:
        # re-raise with context
        raise
```

