from scipy.spatial.distance import euclidean
from numbers import Number

def task_func(points):
    """
    Calculate Euclidean distances between consecutive 2D points.

    Parameters:
      points: list of tuples/lists/numbers
        Each item should be either:
          - a 2-element sequence (x, y),
          - a 1-element sequence (v,) meaning (v, v),
          - or a bare number v meaning (v, v).

    Returns:
      list of floats: distances between consecutive points.
      Returns [] if points is empty or contains a single point.

    Example:
      >>> task_func([(1, 2), (4), (-1.2, 4)])
      [3.605551275463989, 5.2]
    """
    if not points or len(points) < 2:
        return []

    def to_xy(p):
        if isinstance(p, Number):
            return float(p), float(p)
        try:
            seq = list(p)
        except TypeError:
            raise ValueError(f"Invalid point: {p!r}")
        if len(seq) == 0:
            raise ValueError(f"Invalid (empty) point: {p!r}")
        if len(seq) == 1:
            return float(seq[0]), float(seq[0])
        return float(seq[0]), float(seq[1])

    coords = [to_xy(pt) for pt in points]
    return [euclidean(coords[i], coords[i + 1]) for i in range(len(coords) - 1)]

Here's a self-contained Python function that tries to use pandastream if available, but falls back to a plain-Python implementation if not. It counts occurrences of values for the keys "x", "y" and "z" from a list of dictionaries d and returns a dict mapping each key to a dict of value->count.

```python
from collections import defaultdict
from typing import List, Dict, Any

def count_xyz(d: List[Dict[str, Any]]) -> Dict[str, Dict[Any, int]]:
    """
    Count occurrences of values for keys 'x', 'y' and 'z' in a list of dicts d.

    Returns:
      {
        'x': {value1: count, value2: count, ...},
        'y': {...},
        'z': {...}
      }

    This will attempt to use the pandastream library if present; if not,
    a plain-Python counting implementation is used.
    """
    keys = ("x", "y", "z")

    # Try to use pandastream if available (best-effort; fallback if API differs)
    try:
        import pandastream as ps  # type: ignore
    except Exception:
        ps = None

    if ps is not None:
        try:
            # Try some common pandastream patterns in a forgiving way.
            # We'll at least leverage the library to stream the input if possible,
            # but we also prepare a safe fallback to plain iteration.
            Stream = getattr(ps, "Stream", None)
            if Stream is not None:
                # try create a stream from iterable
                try:
                    s = Stream.from_iterable(d)
                except Exception:
                    s = Stream(d)
            else:
                # try a module-level factory
                s = getattr(ps, "from_iterable", None)
                if callable(s):
                    s = s(d)
                else:
                    s = None

            # If we managed to make a stream, try to produce pairs (key, value)
            if s is not None:
                pairs = []
                for item in d:
                    for k in keys:
                        if k in item:
                            pairs.append((k, item[k]))

                # If stream type supports from_iterable, use it to iterate pairs
                if Stream is not None:
                    try:
                        sp = Stream.from_iterable(pairs)
                        # If there's a group-by or count API, try to use it; otherwise iterate
                        if hasattr(sp, "group_by"):
                            groups = sp.group_by(lambda p: p[0])
                            result = {}
                            for gk, group in groups.items():
                                cnt = {}
                                for _, v in group:
                                    cnt[v] = cnt.get(v, 0) + 1
                                result[gk] = cnt
                            # ensure keys with no values are present
                            for k in keys:
                                result.setdefault(k, {})
                            return result
                        else:
                            # iterate the stream to count
                            result = {k: {} for k in keys}
                            for k, v in sp:
                                result.setdefault(k, {})
                                result[k][v] = result[k].get(v, 0) + 1
                            return result
                    except Exception:
                        # If any pandastream-specific handling fails, fall through to pure-python fallback
                        pass
        except Exception:
            pass

    # Pure-Python fallback (guaranteed to work)
    out: Dict[str, Dict[Any, int]] = {k: {} for k in keys}
    for item in d:
        for k in keys:
            if k in item:
                v = item[k]
                out[k][v] = out[k].get(v, 0) + 1
    return out

