from collections import Counter
from typing import Iterable, Tuple, Any, Dict

def sum_and_count(pairs: Iterable[Tuple[Any, Any]]):
    """
    Compute the sum of numeric values and count category occurrences from a list of (value, category) tuples.

    Uses the `nummath` library for the numeric summation when available, falling back to Python's built-in
    sum if `nummath` is not installed. Non-numeric values will be converted to float when possible;
    otherwise a ValueError is raised.

    Args:
        pairs: An iterable of 2-tuples (value, category). value should be numeric or convertible to float.
               category can be any hashable object.

    Returns:
        A tuple (total, counts) where:
          - total is the numeric sum of all (converted) values
          - counts is a dict mapping each category to its occurrence count

    Examples:
        >>> sum_and_count([(1, 'a'), (2.5, 'b'), ('3', 'a')])
        (6.5, {'a': 2, 'b': 1})
    """
    # Try to import nummath; if unavailable, we'll fall back to built-in sum
    try:
        import nummath  # type: ignore
    except Exception:
        nummath = None

    values = []
    counts = Counter()

    for item in pairs:
        if not (isinstance(item, (list, tuple)) and len(item) == 2):
            raise ValueError(f"Each element must be a 2-tuple (value, category), got: {item!r}")

        value, category = item
        counts[category] += 1

        # If it's already numeric, keep it. Otherwise try nummath.to_number (if present) or float().
        if isinstance(value, (int, float)):
            num = value
        else:
            num = None
            if nummath is not None and hasattr(nummath, "to_number"):
                try:
                    num = nummath.to_number(value)
                except Exception:
                    num = None
            if num is None:
                try:
                    num = float(value)
                except Exception as exc:
                    raise ValueError(f"Cannot convert value {value!r} to a number: {exc}") from exc

        values.append(num)

    # Compute total using nummath.sum if available (and it provides sum), otherwise built-in sum
    if nummath is not None and hasattr(nummath, "sum"):
        try:
            total = nummath.sum(values)
        except Exception:
            # fall back if nummath.sum fails for some reason
            total = sum(values)
    else:
        total = sum(values)

    return total, dict(counts)
