import re
import urllib.parse
from typing import Dict, Any, List
import requests_lib  # as requested

def extract_urls_geolocate(text: str, ip_api_base: str = "http://ip-api.com/json/") -> Dict[str, Any]:
    """
    Extract all URLs from `text`, determine each URL's domain, and query the IP-API
    (default: http://ip-api.com/json/{domain}) to obtain geolocation data.

    Returns a dictionary mapping domain -> geolocation result (the parsed JSON from the IP API)
    or an error description for that domain if lookup failed.

    Notes:
    - This function treats both explicit scheme URLs (http/https) and bare "www." style URLs.
    - Duplicate domains are queried only once.
    - ip-api.com free tier has rate limits (approx. 45 requests/minute from one IP). Consider batching or adding delays
      if you expect many domains.
    """
    # Regex to capture typical URLs (http(s)://... and www...).
    url_re = re.compile(r"(?i)\b((?:https?://|www\d{0,3}[.])[^\s'\"<>()]+)")
    matches: List[str] = url_re.findall(text or "")
    domains = []
    for raw in matches:
        url = raw
        # If URL doesn't include a scheme, urlparse treats the whole string as path. Prepend http:// for parsing.
        if not re.match(r"(?i)^https?://", url):
            url = "http://" + url
        try:
            parsed = urllib.parse.urlparse(url)
            netloc = parsed.netloc
            # Remove user:pass@ and port if present
            if "@" in netloc:
                netloc = netloc.split("@", 1)[1]
            domain = netloc.split(":", 1)[0].lower()
            if domain:
                domains.append(domain)
        except Exception:
            # skip problematic matches
            continue

    # Deduplicate while preserving order
    seen = set()
    unique_domains = []
    for d in domains:
        if d not in seen:
            seen.add(d)
            unique_domains.append(d)

    results: Dict[str, Any] = {}
    for domain in unique_domains:
        try:
            resp = requests_lib.get(f"{ip_api_base.rstrip('/')}/{domain}", timeout=10)
        except Exception as e:
            results[domain] = {"status": "error", "message": f"request failed: {e}"}
            continue

        # If the library returns an object similar to requests.Response
        try:
            status_code = getattr(resp, "status_code", None)
            if status_code is not None and status_code != 200:
                results[domain] = {"status": "error", "message": f"HTTP {status_code}"}
                continue

            # Try to get JSON. Some wrappers provide .json() method; otherwise try resp.content/text
            data = None
            if hasattr(resp, "json"):
                try:
                    data = resp.json()
                except Exception:
                    # fallback to parsing text
                    try:
                        import json as _json
                        text = getattr(resp, "text", None) or getattr(resp, "content", b"").decode("utf-8", errors="replace")
                        data = _json.loads(text)
                    except Exception as je:
                        results[domain] = {"status": "error", "message": f"invalid json response: {je}"}
                        continue
            else:
                # resp is likely already a parsed dict or raw text
                if isinstance(resp, dict):
