                        except Exception:
                            stopset = None
        except Exception:
            stopset = None

    # final fallback stopword list (small)
    if stopset is None:
        stopset = {
            'a', 'an', 'and', 'the', 'is', 'are', 'in', 'on', 'for', 'to',
            'of', 'with', 'that', 'this', 'it', 'by', 'from', 'as', 'at',
            'be', 'or', 'was', 'were', 'which', 'but', 'not', 'have', 'has'
